#include <linux/slab.h>
#include <linux/string.h>
#include <linux/kernel.h>

char *build_unc_path(const struct smb_vol *vol, const struct cifs_sb_info *cifs_sb)
{
    const char *unc = vol->UNC;
    const char *prepath = vol->prepath;
    size_t unc_len = strlen(unc);
    size_t prepath_len = prepath ? strlen(prepath) : 0;
    char *full_path;
    size_t total_len = unc_len + prepath_len + 1; // +1 for null terminator

    if (total_len <= unc_len) {
        return ERR_PTR(-EINVAL); // Prevent overflow in case prepath is maliciously large
    }

    full_path = kmalloc(total_len, GFP_KERNEL);
    if (!full_path)
        return ERR_PTR(-ENOMEM);

    strcpy(full_path, unc);

    if (prepath_len) {
        if (prepath[0] != '/') {
            // Ensure prepath starts with slash
            if (strncmp(full_path + (unc_len - 1), "/.", 2) != 0) {
                strcat(full_path, "/");
            }
        }
        strncat(full_path, prepath, prepath_len);
    }

    // Convert any backslashes to forward slashes if needed
    char *p = full_path;
    while ((p = strchr(p, '\\'))) {
        *p = '/';
    }

    pr_debug("Constructed UNC path: %s\n", full_path);

    return full_path;
}
